-- Hestia · 01 · Core: schemas, helpers, members, settings, activity log, audit triggers.
--
-- Conventions used by every "synced" table (see docs/DATA_MODEL.md):
--   id          primary key, generated by the client (uuid) so offline writes are idempotent upserts
--   created_at  set once
--   updated_at  set by the server on every write (the clients' incremental sync cursor)
--   updated_by  member who made the change (forced to the signed-in adult; free for the kiosk and the server)
--   updated_via 'app' | 'kiosk' | 'intercom' | 'mcp' | 'gcal' | 'system'
--   deleted_at  soft delete (tombstone, so offline clients learn about deletions)
-- Nothing personal lives in this file: names, emails and family data are inserted separately (docs/SETUP.md).

create schema if not exists private; -- never exposed through the Data API

-- ---------- Small helpers ----------
-- Accent-insensitive key for names ("Œufs " -> "oeufs"). Accents are replaced before lower(), so the result does not
-- depend on the database's locale.
create or replace function private.norm(t text) returns text
language sql immutable set search_path = '' as $$
  select btrim(regexp_replace(lower(
    translate(replace(replace(replace(replace(coalesce(t, ''), 'œ', 'oe'), 'Œ', 'oe'), 'æ', 'ae'), 'Æ', 'ae'),
      'àâäáãåçéèêëíìîïñóòôöõúùûüýÿÀÂÄÁÃÅÇÉÈÊËÍÌÎÏÑÓÒÔÖÕÚÙÛÜÝ',
      'aaaaaaceeeeiiiinooooouuuuyyaaaaaaceeeeiiiinooooouuuuy')),
    '[^a-z0-9]+', ' ', 'g'))
$$;

-- 64 hex characters of randomness (no extension needed)
create or replace function private.random_token() returns text
language sql volatile set search_path = '' as $$
  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
$$;

create or replace function private.sha256_hex(t text) returns text
language sql immutable set search_path = '' as $$
  select encode(sha256(convert_to(t, 'utf8')), 'hex')
$$;

-- ---------- Members ----------
create table public.members (
  id uuid primary key default gen_random_uuid(),
  auth_user_id uuid unique references auth.users (id) on delete set null,
  name text not null,
  role text not null default 'adult' check (role in ('adult', 'child', 'device')),
  -- true: this member cannot go anywhere alone, every event that concerns them needs a caregiver
  needs_caregiver boolean not null default false,
  color text not null default '#1f6f78',
  emoji text,
  aliases text[] not null default '{}', -- other words that mean this member, in calendar titles and by voice
  birth_date date,
  sort_order int not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.members (id) on delete set null,
  updated_via text not null default 'app',
  deleted_at timestamptz
);
comment on table public.members is 'People of the household (adults, children) and shared devices (the kitchen kiosk).';

-- Who is calling (null for the server)
create or replace function private.current_member_id() returns uuid
language sql stable security definer set search_path = '' as $$
  select m.id from public.members m
  where m.auth_user_id = (select auth.uid()) and m.active and m.deleted_at is null
  limit 1
$$;
create or replace function private.is_family() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.members m
    where m.auth_user_id = (select auth.uid()) and m.active and m.deleted_at is null)
$$;
create or replace function private.is_adult() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.members m
    where m.auth_user_id = (select auth.uid()) and m.active and m.deleted_at is null and m.role = 'adult')
$$;

-- ---------- Settings (household-wide key/value) ----------
create table public.settings (
  id text primary key,
  value jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.members (id) on delete set null,
  updated_via text not null default 'app',
  deleted_at timestamptz
);
comment on table public.settings is 'Household settings. Known ids: household, reminders (see docs/DATA_MODEL.md).';

-- The household's time zone and "today" there
create or replace function private.tz() returns text
language sql stable security definer set search_path = '' as $$
  select coalesce((select value ->> 'timezone' from public.settings where id = 'household'), 'America/Toronto')
$$;
create or replace function private.today() returns date
language sql stable security definer set search_path = '' as $$
  select (now() at time zone private.tz())::date
$$;

-- ---------- Activity log (append-only) ----------
create table public.activity_log (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  actor_id uuid references public.members (id) on delete set null,
  via text not null default 'app',
  action text not null,       -- create | update | delete | restore | purchased | needed | unneeded | done | reopened | skipped | approval_requested | approved | declined | cancelled
  entity_type text not null,  -- table name
  entity_id text not null,
  label text,                 -- the row's name at that time ("Œufs")
  data jsonb                  -- create: the row; update: {field: [old, new]}
);
create index activity_log_at on public.activity_log (at desc);
create index activity_log_entity on public.activity_log (entity_type, entity_id, at desc);
create index activity_log_action on public.activity_log (entity_type, action, at desc);
comment on table public.activity_log is 'Who did what, when and from where. Written by triggers only; the base for statistics.';

-- ---------- Triggers shared by every synced table ----------
-- BEFORE INSERT OR UPDATE: server time and the real author.
create or replace function private.touch() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  me record;
begin
  new.updated_at := clock_timestamp();
  if tg_op = 'INSERT' then
    new.created_at := coalesce(new.created_at, new.updated_at);
  else
    new.created_at := old.created_at;
  end if;
  if (select auth.uid()) is not null then
    select m.id, m.role into me from public.members m where m.auth_user_id = (select auth.uid()) limit 1;
    -- A person writing over a generated row (ticking a chore) is not "system"; writes made by other triggers stay as they are
    if new.updated_via = 'system' and pg_trigger_depth() = 1 then new.updated_via := 'app'; end if;
    if me.role = 'adult' then
      new.updated_by := me.id; -- a signed-in adult cannot write in someone else's name
    elsif me.role = 'device' then
      new.updated_by := coalesce(new.updated_by, me.id); -- the kiosk says who touched the screen, when it knows
      if new.updated_via is null or new.updated_via = 'app' then new.updated_via := 'kiosk'; end if;
    end if;
  end if;
  new.updated_via := coalesce(new.updated_via, 'app');
  return new;
end $$;

-- AFTER INSERT OR UPDATE: one line in the activity log. TG_ARGV[0]: the column that names the row.
create or replace function private.audit() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  n jsonb := to_jsonb(new);
  o jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) end;
  diff jsonb;
  act text;
  quiet constant text[] := array['updated_at', 'updated_by', 'updated_via', 'created_at',
    'gcal_etag', 'gcal_synced_at', 'gcal_dirty', 'name_key', 'purchase_count', 'needed_at'];
begin
  if new.updated_via = 'system' then return null; end if; -- generated rows (chore occurrences) are not somebody's act
  if tg_op = 'INSERT' then
    act := 'create';
    diff := n - quiet;
  else
    select jsonb_object_agg(a.key, jsonb_build_array(b.value, a.value)) into diff
    from jsonb_each(n) a join jsonb_each(o) b using (key)
    where a.value is distinct from b.value and not (a.key = any (quiet));
    if diff is null then return null; end if; -- nothing really changed (a sync replay)
    act := case
      when n ->> 'deleted_at' is not null and o ->> 'deleted_at' is null then 'delete'
      when n ->> 'deleted_at' is null and o ->> 'deleted_at' is not null then 'restore'
      else 'update' end;
    if act = 'update' then
      if tg_table_name = 'shopping_items' and diff ? 'needed' then
        act := case when (n ->> 'needed')::boolean then 'needed'
                    when diff ? 'purchased_at' then 'purchased' else 'unneeded' end;
      elsif tg_table_name = 'chore_occurrences' and diff ? 'status' then
        act := case n ->> 'status' when 'done' then 'done' when 'skipped' then 'skipped' else 'reopened' end;
      elsif tg_table_name = 'events' and diff ? 'status' then
        act := case n ->> 'status'
          when 'pending' then 'approval_requested'
          when 'confirmed' then case when o ->> 'status' = 'pending' then 'approved' else 'update' end
          when 'declined' then 'declined'
          when 'cancelled' then 'cancelled'
          else 'update' end;
      end if;
    end if;
  end if;
  insert into public.activity_log (actor_id, via, action, entity_type, entity_id, label, data)
  -- (the author is looked up: a member removed for good, which sets these columns to null row by row, must not block)
  values ((select m.id from public.members m where m.id = new.updated_by), new.updated_via, act, tg_table_name, n ->> 'id', n ->> tg_argv[0], diff);
  return null;
end $$;

-- Attaches both triggers and the access rule to a table: the family reads and writes; with adults_write, everyone in the
-- family reads and only adults change.
create or replace function private.setup_synced_table(tbl text, label_column text, adults_write boolean default false) returns void
language plpgsql security definer set search_path = '' as $$
begin
  execute format('create trigger touch before insert or update on public.%I for each row execute function private.touch()', tbl);
  execute format('create trigger audit after insert or update on public.%I for each row execute function private.audit(%L)', tbl, label_column);
  execute format('create index %I on public.%I (updated_at)', tbl || '_updated_at', tbl);
  execute format('alter table public.%I enable row level security', tbl);
  if adults_write then
    execute format('create policy family_read on public.%I for select to authenticated using ((select private.is_family()))', tbl);
    execute format('create policy adults_write on public.%I for all to authenticated using ((select private.is_adult())) with check ((select private.is_adult()))', tbl);
  else
    execute format('create policy family on public.%I for all to authenticated using ((select private.is_family())) with check ((select private.is_family()))', tbl);
  end if;
  execute format('revoke all on public.%I from anon', tbl);
  execute format('grant select, insert, update, delete on public.%I to authenticated', tbl);
end $$;

select private.setup_synced_table('members', 'name', true);
select private.setup_synced_table('settings', 'id', true);

alter table public.activity_log enable row level security;
create policy family_read on public.activity_log for select to authenticated using ((select private.is_family()));
revoke all on public.activity_log from anon;
revoke all on public.activity_log from authenticated;
grant select on public.activity_log to authenticated;

-- Functions of "private" are called by the access rules: the signed-in role must be able to run the three checks, nothing else
grant usage on schema private to authenticated;
revoke execute on all functions in schema private from public, anon, authenticated;
grant execute on function private.is_family(), private.is_adult(), private.current_member_id(), private.tz(), private.today() to authenticated;
alter default privileges in schema private revoke execute on functions from public;

-- Defaults that say nothing about the family
insert into public.settings (id, value, updated_via) values
  ('household', '{"name": "Hestia", "timezone": "America/Toronto", "locale": "fr-CA",
                  "weather": {"label": "Montréal", "latitude": 45.5019, "longitude": -73.5674}}', 'system'),
  ('reminders', '{"morning": "07:30", "evening": "20:00", "event_minutes_before": 60}', 'system')
on conflict (id) do nothing;
